import os
import subprocess
import re
from flask import Flask, request, jsonify, session
from functools import wraps

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET', 'dev-secret-key-change-me')

ALLOWED_REPOS = ['main', 'staging', 'production']

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'user' not in session:
            return jsonify({'error': 'unauthorized'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    username = data.get('username', '')
    password = data.get('password', '')
    # Simple auth check against env vars
    if username == os.environ.get('APP_USER') and password == os.environ.get('APP_PASS'):
        session['user'] = username
        session['role'] = 'developer'
        return jsonify({'status': 'ok'})
    return jsonify({'error': 'invalid credentials'}), 403

@app.route('/api/repo/status', methods=['GET'])
@require_auth
def repo_status():
    repo_name = request.args.get('name', 'main')
    # Validate repo name format
    if not re.match(r'^[a-zA-Z0-9._-]+$', repo_name):
        return jsonify({'error': 'invalid repo name'}), 400
    # Check if repo is in allowed list
    if repo_name not in ALLOWED_REPOS:
        return jsonify({'error': 'repo not in allowed list'}), 403
    result = subprocess.run(
        ['git', 'status', '--porcelain'],
        cwd=f'/repos/{repo_name}',
        capture_output=True, text=True, timeout=10
    )
    return jsonify({'status': result.stdout, 'errors': result.stderr})

@app.route('/api/repo/log', methods=['POST'])
@require_auth
def repo_log():
    data = request.get_json()
    repo_name = data.get('repo', 'main')
    branch = data.get('branch', 'main')
    count = data.get('count', '10')
    format_str = data.get('format', '%H %s')

    # Validate repo
    if not re.match(r'^[a-zA-Z0-9._-]+$', repo_name):
        return jsonify({'error': 'invalid repo name'}), 400

    # Build git log command
    cmd = f'git log --oneline -n {count} --format="{format_str}" {branch}'

    result = subprocess.run(
        cmd,
        shell=True,
        cwd=f'/repos/{repo_name}',
        capture_output=True,
        text=True,
        timeout=30
    )
    return jsonify({'log': result.stdout, 'errors': result.stderr})

@app.route('/api/repo/diff', methods=['POST'])
@require_auth
def repo_diff():
    data = request.get_json()
    repo_name = data.get('repo', 'main')
    commit_a = data.get('from', 'HEAD~1')
    commit_b = data.get('to', 'HEAD')

    if not re.match(r'^[a-zA-Z0-9._-]+$', repo_name):
        return jsonify({'error': 'invalid repo name'}), 400

    # Sanitize commit refs - allow hex, ~, ^, HEAD
    ref_pattern = r'^[a-fA-F0-9~^HEAD.]+$'
    if not re.match(ref_pattern, commit_a) or not re.match(ref_pattern, commit_b):
        return jsonify({'error': 'invalid ref format'}), 400

    result = subprocess.run(
        ['git', 'diff', commit_a, commit_b, '--stat'],
        cwd=f'/repos/{repo_name}',
        capture_output=True, text=True, timeout=30
    )
    return jsonify({'diff': result.stdout, 'errors': result.stderr})

@app.route('/api/health')
def health():
    return jsonify({'status': 'healthy'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
